import 'dart:convert';
import 'dart:io';

import 'package:movement_core/movement_core.dart';
import 'package:test/test.dart';

/// Real cross-language verification, NOT a Dart-internal round trip.
/// project_json_test.dart's own tests all go Dart toJson() -> jsonEncode
/// -> jsonDecode -> Dart fromJson(), compared against the SAME in-memory
/// Dart object - that only proves the Dart codec is self-consistent, it
/// says nothing about actually matching what movement-core's JS engine
/// produces.
///
/// This fixture (js_reference_project.json) was generated by ACTUALLY
/// RUNNING movement-core's own JS code (movement-core/src/model/
/// project.js's createLayer/addKeyframe/track, core/interpolation.js's
/// autoComputeTangents, effects/geometryEffectRegistry.js's
/// createEffectInstance for mesh_warp) via a throwaway Node script
/// (movement-core/src/gen_fixture.mjs, not committed - see its own doc
/// comment), serialized in the EXACT envelope shape src/io/saveLoad.js's
/// saveProjectToFile() builds. The values asserted below were read back
/// out of that real JS-produced file, not computed independently in
/// Dart - this test would fail if projectLayersFromJson misparsed
/// anything the JS side actually writes (wrong key name, wrong
/// track/keyframe shape, dropped optional field, etc).
void main() {
  late Map<String, dynamic> fixture;
  late Layer layer; // the JS-side "js_reference_layer"
  late Layer nullLayer; // the JS-side "js_null_layer" (createLayer("null"))
  late List<Layer> allLayers;

  setUpAll(() {
    final file = File('test/fixtures/js_reference_project.json');
    fixture = jsonDecode(file.readAsStringSync()) as Map<String, dynamic>;
  });

  setUp(() {
    final layersJson = (fixture['project'] as Map<String, dynamic>)['layers'] as List<dynamic>;
    final layers = projectLayersFromJson(layersJson);
    expect(layers.length, equals(4), reason: 'JS side pushed 2 extra layers onto its own 2 default layers');
    expect(layers[0].id, equals('L_parent'));
    expect(layers[0].name, equals('controller'));
    expect(layers[1].id, equals('L_child'));
    expect(layers[1].name, equals('object_a'));
    allLayers = layers;
    layer = layers[2];
    nullLayer = layers[3];
  });

  test('parentId chain (L_parent <- L_child <- js_reference_layer) resolves to real layers after round-trip, not just surviving strings', () {
    expect(allLayers[0].parentId, isNull);
    expect(allLayers[1].parentId, equals('L_parent'));
    expect(layer.parentId, equals('L_child'));
    // the actual referential-integrity claim: these ids resolve to real
    // layers in the RESTORED list, not just to strings that happen to
    // match - findLayer is the same lookup the engine itself uses
    // everywhere else (getLayerStateAt's parent-chain walk included).
    expect(findLayer(Project(layers: allLayers), allLayers[1].parentId), same(allLayers[0]));
    expect(findLayer(Project(layers: allLayers), layer.parentId), same(allLayers[1]));
  });

  test('null-shaped layer: color survives as an explicit null, not a missing/default field', () {
    expect(nullLayer.name, equals('js_null_layer'));
    expect(nullLayer.content.shape, equals('null'));
    // createLayer()'s own rule (movement-core/src/model/project.js):
    // presetShape === "null" ? null : LAYER_PALETTE[...] - a real null
    // layer always serializes color as JSON `null`, not an omitted key
    // (L_parent, the OTHER layer with no color, omits the key entirely
    // since its object literal never set color at all - a materially
    // different JSON shape this test is careful to distinguish from).
    expect(nullLayer.color, isNull);
    expect(nullLayer.parentId, isNull);
  });

  test('envelope: version/maxFrame/playbackSpeed/selectedLayer match saveProjectToFile\'s own shape', () {
    expect(fixture['version'], equals(1));
    expect(fixture['maxFrame'], equals(240));
    expect(fixture['playbackSpeed'], equals(1.5));
    expect(fixture['selectedLayer'], equals(layer.id));
  });

  test('basic layer identity', () {
    expect(layer.name, equals('js_reference_layer'));
    expect(layer.content.shape, equals('rect'));
  });

  test('anchor track: default/spatial/loop/tension/globalEasing all survive from real JS output', () {
    final anchor = layer.transform.anchor;
    expect(anchor.defaultValue, equals([0.5, 0.5]));
    expect(anchor.spatial, isTrue);
    expect(anchor.loop, isTrue);
    expect(anchor.tension, closeTo(0.65, 1e-9));
    expect(anchor.globalEasing, isNotNull);
    expect(anchor.globalEasing!.x1, closeTo(0.33, 1e-9));
    expect(anchor.globalEasing!.x2, closeTo(0.67, 1e-9));
  });

  test('anchor keyframes: frames/values/named-easing temporal curves match what addKeyframe(..., "easeIn"/"easeInOut"/"easeOut") actually wrote', () {
    final kfs = layer.transform.anchor.keyframes;
    expect(kfs.length, equals(3));

    expect(kfs[0].frame, equals(0));
    expect(kfs[0].value, equals([0.1, 0.2]));
    expect(kfs[0].temporal.x1, closeTo(0.42, 1e-9)); // easeIn
    expect(kfs[0].temporal.x2, closeTo(1, 1e-9));

    expect(kfs[1].frame, equals(30));
    expect(kfs[1].value, equals([0.4, 0.6]));
    expect(kfs[1].temporal.x1, closeTo(0.42, 1e-9)); // easeInOut
    expect(kfs[1].temporal.x2, closeTo(0.58, 1e-9));

    expect(kfs[2].frame, equals(60));
    expect(kfs[2].value, equals([0.9, 0.15]));
    expect(kfs[2].temporal.x1, closeTo(0, 1e-9)); // easeOut
    expect(kfs[2].temporal.x2, closeTo(0.58, 1e-9));
  });

  test('anchor spatial tangents: real autoComputeTangents(tension=0.65) output, not [0,0] placeholders', () {
    final kfs = layer.transform.anchor.keyframes;
    // pinned against the actual JS-computed values (catmullRomTangent
    // with k=1-0.65=0.35) read back out of the fixture - regression
    // guard against a Dart-side JSON codec that silently drops or
    // zeroes spatialTangent.
    expect(kfs[0].spatialTangent.outTan[0], closeTo(0.035, 1e-6));
    expect(kfs[0].spatialTangent.outTan[1], closeTo(0.046666666666666, 1e-6));
    expect(kfs[1].spatialTangent.outTan[0], closeTo(0.046666666666666, 1e-6));
    expect(kfs[1].spatialTangent.outTan[1], closeTo(-0.0029166666666666, 1e-6));
    expect(kfs[2].spatialTangent.inTan[0], closeTo(-0.058333333333333, 1e-6));
    expect(kfs[2].spatialTangent.inTan[1], closeTo(0.0525, 1e-6));
  });

  test('rotation track: expression field survives (a track-level extra JS sets ad hoc, not in the base track() factory)', () {
    final rotation = layer.transform.rotation;
    expect(rotation.expression, equals("layer('js_reference_layer').rotation + 5"));
    expect(rotation.keyframes.map((k) => k.frame), equals([0, 60]));
    expect(rotation.keyframes.map((k) => k.value), equals([0, 270]));
  });

  test('opacity track: plain scalar keyframes with a named easing preset', () {
    final opacity = layer.transform.opacity;
    expect(opacity.keyframes[0].value, equals(1));
    expect(opacity.keyframes[1].value, equals(0.25));
    expect(opacity.keyframes[1].temporal.x2, closeTo(0.58, 1e-9)); // easeOut
  });

  test('mask: mode/sourceLayerId/feather track (added via addKeyframe(..., "mask:0"))', () {
    expect(layer.masks.length, equals(1));
    final mask = layer.masks.single;
    expect(mask.enabled, isTrue);
    expect(mask.mode, equals('intersect'));
    expect(mask.sourceLayerId, equals('L_child'));
    expect(mask.feather.keyframes.single.frame, equals(0));
    expect(mask.feather.keyframes.single.value, equals(4));
  });

  test('mesh_warp effect instance: plain rows/cols ints vs. Track pin params, matching createEffectInstance\'s real output shape', () {
    expect(layer.effectStack.length, equals(1));
    final inst = layer.effectStack.single;
    expect(inst.effectId, equals('mesh_warp'));
    expect(inst.params['rows'], equals(4)); // plain int, not a Track - createEffectInstance sets this directly
    expect(inst.params['cols'], equals(4));
    expect(inst.params['rows'], isNot(isA<Track>()));

    final r0c0 = inst.params['r0c0'] as Track;
    expect(r0c0.defaultValue, equals([0.02, -0.03]));
    expect(r0c0.keyframes, isEmpty);

    final r3c3 = inst.params['r3c3'] as Track;
    expect(r3c3.keyframes.length, equals(2));
    expect(r3c3.keyframes[1].frame, equals(60));
    expect(r3c3.keyframes[1].value, equals([0.07, 0.11]));
  });

  test('motionBlur/wiggle/pendulum: non-default settings all round-trip byte-for-value from real JS output', () {
    expect(layer.motionBlur.enabled, isTrue);
    expect(layer.motionBlur.shutterAngle, equals(270));
    expect(layer.motionBlur.samples, equals(12));

    expect(layer.wiggle.enabled, isTrue);
    expect(layer.wiggle.speed, equals(12));
    expect(layer.wiggle.amplitude, equals(33));
    expect(layer.wiggle.smoothness, equals(55));

    expect(layer.pendulum.enabled, isTrue);
    expect(layer.pendulum.frequency, equals(44));
    expect(layer.pendulum.damping, equals(15));
    expect(layer.pendulum.sensitivity, equals(77));
    expect(layer.pendulum.maxAngle, equals(35));
    expect(layer.pendulum.freeze, equals(45));
    expect(layer.pendulum.rotateWithLine, isFalse); // non-default (JS default is true) - confirms this isn't just reading a constructor default
    expect(layer.pendulum.pivotOffset.defaultValue, equals([0.01, -0.02]));
    // pivotOffset is created via track([...], true) - JS's spatial=true
    // is what makes autoComputeTangents apply to it at all. Asserted
    // explicitly here rather than assumed from trackToJson/FromJson
    // being shared code with the anchor track above - pendulumFromJson
    // has its own optional-field branch (`j['pivotOffset'] != null ?
    // trackFromJson(...) : null`) that could in principle drop it.
    expect(layer.pendulum.pivotOffset.spatial, isTrue);
    expect(layer.pendulum.pivotOffset.keyframes.length, equals(2));
    expect(layer.pendulum.pivotOffset.keyframes[1].value, equals([0.02, 0.03]));
  });
}
